-- PostgreSQL / Neon. Ejecutar sobre la base seleccionada en Neon.
-- No crea otra base, no borra tablas y no incluye usuarios ni claves de prueba.
BEGIN;
CREATE TABLE IF NOT EXISTS "Clientes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_Clientes" PRIMARY KEY,
    "Nombre" varchar(80) NOT NULL,
    "Apellido" varchar(80) NOT NULL,
    "Dni" varchar(8) NOT NULL,
    "Telefono" varchar(20) NOT NULL,
    "Email" varchar(120) NOT NULL
);
CREATE TABLE IF NOT EXISTS "Mascotas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_Mascotas" PRIMARY KEY,
    "Nombre" varchar(80) NOT NULL,
    "Especie" varchar(50) NOT NULL,
    "Raza" varchar(80) NOT NULL,
    "Edad" integer NOT NULL CONSTRAINT "CK_Mascotas_Edad" CHECK ("Edad" BETWEEN 0 AND 30),
    "ClienteId" integer NOT NULL,
    CONSTRAINT "FK_Mascotas_Clientes" FOREIGN KEY ("ClienteId")
        REFERENCES "Clientes" ("Id") ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS "IX_Mascotas_ClienteId" ON "Mascotas" ("ClienteId");
CREATE TABLE IF NOT EXISTS "Usuarios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_Usuarios" PRIMARY KEY,
    "Correo" varchar(120) NOT NULL,
    "ClaveHash" varchar(100) NOT NULL,
    "Rol" varchar(30) NOT NULL,
    CONSTRAINT "CK_Usuarios_Rol" CHECK ("Rol" IN ('Recepcionista', 'Veterinario'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "UX_Usuarios_Correo" ON "Usuarios" ("Correo");
COMMIT;
